import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(const float* __restrict__ input,
                              const float* __restrict__ weight,
                              const float* __restrict__ bias,
                              float* __restrict__ output,
                              int N, int C_in, int H_in, int W_in,
                              int C_out, int H_out, int W_out,
                              int K, int stride, int pad) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int tmp = idx / W_out;
    int h_out = tmp % H_out;
    tmp /= H_out;
    int c_out = tmp % C_out;
    int n = tmp / C_out;

    int h_base = h_out * stride - pad;
    int w_base = w_out * stride - pad;

    float acc = bias[c_out];

    for (int c = 0; c < C_in; ++c) {
        const float* in_ch = input + ((n * C_in + c) * H_in) * W_in;
        const float* w_ch = weight + ((c_out * C_in + c) * K) * K;
        #pragma unroll
        for (int kh = 0; kh < 11; ++kh) {
            int h_in = h_base + kh;
            if (h_in < 0 || h_in >= H_in) continue;
            #pragma unroll
            for (int kw = 0; kw < 11; ++kw) {
                int w_in = w_base + kw;
                if (w_in < 0 || w_in >= W_in) continue;
                acc += in_ch[h_in * W_in + w_in] * w_ch[kh * K + kw];
            }
        }
    }
    output[idx] = acc;
}

torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t pad) {
    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);
    int C_out = weight.size(0);
    int K = weight.size(2);
    int H_out = (H_in + 2 * pad - K) / stride + 1;
    int W_out = (W_in + 2 * pad - K) / stride + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    int total = N * C_out * H_out * W_out;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    conv2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, H_out, W_out,
        K, (int)stride, (int)pad);

    return output;
}
'''

cpp_src = "torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int64_t stride, int64_t pad);"

_conv_module = load_inline(
    name="conv2d_custom_cuda",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        return _conv_module.conv2d_forward(
            x.contiguous(),
            self.conv1.weight.contiguous(),
            self.conv1.bias.contiguous(),
            self.conv1.stride[0],
            self.conv1.padding[0],
        )

